48	// TestCrossProcessSameProposal：多个进程同时执行同一提案，
49	// 只能有一份成功凭据；其余进程拿到同一份凭据（重试语义），不得二次扣款。
50	func TestCrossProcessSameProposal(t *testing.T) {
51		binary := buildCLI(t)
52		state := filepath.Join(t.TempDir(), "treasury.json")
53		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
54			t.Fatal("init failed")
55		}
56		if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-1",
57			"--timelock", "100", "--action", "transfer:audits:250"); code != 0 {
58			t.Fatal("register failed")
59		}
60	
61		const n = 16
62		var wg sync.WaitGroup
63		codes := make([]int, n)
64		outputs := make([]string, n)
65		start := make(chan struct{})
66		for i := 0; i < n; i++ {
67			wg.Add(1)
68			go func(i int) {
69				defer wg.Done()
70				<-start
71				so, se, code := runCLI(t, binary, state, "execute", "--id", "gip-1",
72					"--now", strconv.Itoa(100+i), "--json")
73				codes[i] = code
74				outputs[i] = so + se
75			}(i)
76		}
77		close(start)
78		wg.Wait()
79	
80		for i, code := range codes {
81			if code != 0 {
82				t.Fatalf("process %d exited %d: %s", i, code, outputs[i])
83			}
84			// 每个进程看到的首次执行时间都必须是 100（最早请求未必胜出，但凭据唯一）。
85			if !strings.Contains(outputs[i], `"executed_at"`) {
86				t.Fatalf("process %d got no receipt: %s", i, outputs[i])
87			}
88		}
89		so, _, code := runCLI(t, binary, state, "receipts", "--json")
90		if code != 0 {
91			t.Fatal("receipts failed")
92		}
93		if strings.Count(so, `"proposal_id"`) != 1 {
94			t.Fatalf("expected exactly one receipt, got:\n%s", so)
95		}
96		if so2, _, _ := runCLI(t, binary, state, "balances", "--json"); !strings.Contains(so2, `"treasury": 750`) {
97			t.Fatalf("treasury must be 750 after single execution:\n%s", so2)
98		}
99	}
