161	// TestCrossProcessCrashConsistency：在并发执行期间反复 SIGKILL 进程，
162	// 状态文件在任何时刻都只能是整项执行前或执行后的完整状态。
163	func TestCrossProcessCrashConsistency(t *testing.T) {
164		binary := buildCLI(t)
165		state := filepath.Join(t.TempDir(), "treasury.json")
166		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000000"); code != 0 {
167			t.Fatal("init failed")
168		}
169		const n = 200
170		for i := 0; i < n; i++ {
171			if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-"+itoa(i),
172				"--timelock", "0", "--action", "transfer:a:1"); code != 0 {
173				t.Fatalf("register %d failed", i)
174			}
175		}
176	
177		// 启动后立刻 SIGKILL：杀死可能落在执行前、写盘前后任意位置。
178		var wg sync.WaitGroup
179		for i := 0; i < n; i++ {
180			wg.Add(1)
181			go func(i int) {
182				defer wg.Done()
183				cmd := exec.Command(binary, "execute", "--state", state, "--id", "gip-"+itoa(i), "--now", "0")
184				if err := cmd.Start(); err != nil {
185					t.Errorf("start %d: %v", i, err)
186					return
187				}
188				if i%3 == 0 {
189					_ = cmd.Process.Kill()
190				}
191				_ = cmd.Wait()
192			}(i)
193		}
194		wg.Wait()
195	
196		// 最终状态必须能严格打开：余额与凭据重放一致；被杀死的执行要么整体发生、要么整体未发生。
197		store, err := Open(state)
198		if err != nil {
199			t.Fatalf("state after crashes is unusable: %v", err)
200		}
201		defer store.Close()
202		treasury, err := store.TreasuryBalance()
203		if err != nil {
204			t.Fatal(err)
205		}
206		receipts, err := store.Receipts()
207		if err != nil {
208			t.Fatal(err)
209		}
210		if int64(len(receipts)) != 1000000-treasury {
211			t.Fatalf("invariant broken: receipts=%d treasury=%d", len(receipts), treasury)
212		}
213		// 每个 executed 提案恰好有凭据；无凭据的提案仍是 passed 且余额未变（重放校验已在 Open 中完成）。
214		executed := map[string]bool{}
215		for _, r := range receipts {
216			if executed[r.ProposalID] {
217				t.Fatalf("duplicate receipt for %s", r.ProposalID)
218			}
219			executed[r.ProposalID] = true
220		}
221		proposals, err := store.Proposals()
222		if err != nil {
223			t.Fatal(err)
224		}
225		for _, p := range proposals {
226			if p.State == "executed" && !executed[p.ID] {
227				t.Fatalf("proposal %s executed without receipt", p.ID)
228			}
229			if p.State == "passed" && executed[p.ID] {
230				t.Fatalf("proposal %s passed but has receipt", p.ID)
231			}
232		}
233	}
