235	// TestCrossProcessVotingLifecycle：通过 CLI 跨进程完成创建→委托投票→计票→执行，
236	// 并验证重复创建/投票/计票的幂等与冲突语义。
237	func TestCrossProcessVotingLifecycle(t *testing.T) {
238		binary := buildCLI(t)
239		state := filepath.Join(t.TempDir(), "treasury.json")
240		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
241			t.Fatal("init failed")
