348	// TestCrossProcessConcurrentTally：多进程同时计票，结论只产生一次且不追加任何记录。
349	func TestCrossProcessConcurrentTally(t *testing.T) {
350		binary := buildCLI(t)
351		state := filepath.Join(t.TempDir(), "treasury.json")
352		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
353			t.Fatal("init failed")
354		}
355		if _, _, code := runCLI(t, binary, state, "create-vote", "--id", "gip-c",
356			"--member", "a:600", "--member", "b:400",
357			"--quorum", "600", "--start", "0", "--deadline", "10", "--timelock", "10",
358			"--action", "transfer:x:1"); code != 0 {
359			t.Fatal("create failed")
360		}
361		if _, _, code := runCLI(t, binary, state, "vote", "--id", "gip-c",
362			"--voter", "a", "--choice", "for", "--now", "5"); code != 0 {
363			t.Fatal("vote failed")
364		}
365		const n = 16
366		var wg sync.WaitGroup
367		start := make(chan struct{})
368		outputs := make([]string, n)
369		for i := 0; i < n; i++ {
370			wg.Add(1)
371			go func(i int) {
372				defer wg.Done()
373				<-start
374				so, _, _ := runCLI(t, binary, state, "tally", "--id", "gip-c",
375					"--now", strconv.Itoa(10+i), "--json")
376				outputs[i] = so
377			}(i)
378		}
379		close(start)
380		wg.Wait()
381		// 首个抢到锁的进程完成首次计票（其 now 未必最小）；其余进程必须拿到同一结论。
382		var winner string
383		for i, out := range outputs {
384			if !strings.Contains(out, `"passed": true`) {
385				t.Fatalf("tally %d diverged or failed: %s", i, out)
386			}
387			m := tallyTimeRe.FindStringSubmatch(out)
388			if m == nil {
389				t.Fatalf("tally %d missing tallied_at: %s", i, out)
390			}
391			if winner == "" {
392				winner = m[1]
393			} else if m[1] != winner {
394				t.Fatalf("tally %d tallied_at=%s, want first result %s", i, m[1], winner)
395			}
396		}
397		so, _, _ := runCLI(t, binary, state, "proposal", "--id", "gip-c", "--json")
398		if strings.Count(so, `"voted_at"`) != 1 {
399			t.Fatalf("ballot records changed under concurrent tally:\n%s", so)
400		}
401	}
402	
403	var tallyTimeRe = mustRegexp(`"tallied_at": (\d+)`)
404	
405	func mustRegexp(pattern string) *regexp.Regexp { return regexp.MustCompile(pattern) }
