718	// TestCLIRejectsIncompleteReceiptOrderIndex：第一份凭据删掉 order、或第一项动作
719	// 删掉 index 时，即使资金变动与动作原文完全一致，所有读取命令也把整份状态判为
720	// 损坏：原因写入 stderr（含提案编号、字段与缺失原因；index 还含动作位置），以
721	// 域错误退出码 1 结束，stdout 不出现任何提案的部分查询结果，文件不被改写。
722	func TestCLIRejectsIncompleteReceiptOrderIndex(t *testing.T) {
723		binary := buildCLI(t)
724		dir := t.TempDir()
725		state := filepath.Join(dir, "treasury.json")
726		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
727			t.Fatal("init failed")
728		}
729		// 同一收款账户连续两项动作：缺损修复不得合并或重排记录。
730		if _, _, code := runCLI(t, binary, state, "register", "--id", "gip-1",
731			"--timelock", "0",
732			"--action", "transfer:acct:100", "--action", "transfer:acct:50"); code != 0 {
733			t.Fatal("register failed")
734		}
735		if so, _, code := runCLI(t, binary, state, "execute", "--id", "gip-1", "--now", "0", "--json"); code != 0 ||
736			!strings.Contains(so, `"order": 0`) || !strings.Contains(so, `"index": 0`) ||
737			!strings.Contains(so, `"index": 1`) {
738			t.Fatalf("first execute should emit full order/index, code=%d so=%s", code, so)
739		}
740		// 正常查询保持不变：文本与 JSON 都输出明确保存的序号。
741		if so, _, code := runCLI(t, binary, state, "receipts"); code != 0 ||
742			!strings.Contains(so, "order=0") || !strings.Contains(so, "action 0:") ||
743			!strings.Contains(so, "action 1:") {
744			t.Fatalf("text receipts query changed: %s", so)
745		}
746	
747		raw, err := os.ReadFile(state)
748		if err != nil {
749			t.Fatal(err)
750		}
751		cases := []struct {
752			name    string
753			edit    func(string) string
754			wantMsg []string
755		}{
756			{
757				name:    "order-missing",
758				edit:    func(s string) string { return strings.Replace(s, `"order": 0,`, ``, 1) },
759				wantMsg: []string{"corrupt", "gip-1", `receipt 0`, `"order"`, "missing"},
760			},
761			{
762				name:    "index-missing",
763				edit:    func(s string) string { return strings.Replace(s, `"index": 0,`, ``, 1) },
764				wantMsg: []string{"corrupt", "gip-1", "action 0", `"index"`, "missing"},
765			},
766		}
767		for _, tc := range cases {
768			t.Run(tc.name, func(t *testing.T) {
769				corrupt := tc.edit(string(raw))
770				if corrupt == string(raw) {
771					t.Fatalf("setup: target field not found")
772				}
773				bad := filepath.Join(dir, tc.name+".json")
774				if err := os.WriteFile(bad, []byte(corrupt), 0o600); err != nil {
775					t.Fatal(err)
776				}
777				for _, args := range [][]string{
778					{"receipt", "--id", "gip-1"},
779					{"receipt", "--id", "gip-1", "--json"},
780					{"receipts"},
781					{"receipts", "--json"},
782					{"balances", "--json"},
783					{"proposals", "--json"},
784				} {
785					so, se, code := runCLI(t, binary, bad, args...)
786					if code != 1 {
787						t.Fatalf("%v exit=%d want 1, stdout=%q stderr=%q", args, code, so, se)
788					}
789					if so != "" {
790						t.Fatalf("%v stdout must stay empty on corruption, got %q", args, so)
791					}
792					for _, want := range tc.wantMsg {
793						if !strings.Contains(se, want) {
794							t.Fatalf("%v stderr %q missing %q", args, se, want)
795						}
796					}
797				}
798				// 不整理、补齐或覆盖缺损文件。
799				if got, err := os.ReadFile(bad); err != nil || string(got) != corrupt {
800					t.Fatalf("corrupt file was modified or rewritten")
801				}
802			})
803		}
804	}
