1076		}
1077		// 普通不含冒号的编号继续按原有方式工作，且冒号编号与普通编号可混用。
1078		mixed := []string{"create-vote", "--id", "gip-mixed",
1079			"--member", "plain:40", "--member", ":alice:30", "--member", "team:bob:30",
1080			"--delegate", ":alice:team:bob", "--delegate", "plain:team:bob",
1081			"--quorum", "100", "--start", "0", "--deadline", "100", "--timelock", "200"}
1082		if _, se, code := runCLI(t, binary, state, mixed...); code != 0 {
1083			t.Fatalf("mixed plain/colon members create exit=%d: %s", code, se)
1084		}
1085		if vo, _, code := runCLI(t, binary, state, "vote", "--id", "gip-mixed",
1086			"--voter", "team:bob", "--choice", "for", "--now", "50", "--json"); code != 0 ||
1087			!strings.Contains(vo, `"weight": 100`) {
1088			t.Fatalf("team:bob should carry all 100 weight: exit=%d so=%s", code, vo)
1089		}
1090	}
1091	
1092	// TestCLIRegisterReportsAcknowledgedState：register 的成功响应必须反映这次登记
1093	// 实际认可的记录——首次登记 already_registered=false、state=passed；相同内容
1094	// 重试 already_registered=true 且保留实际状态：未执行为 passed，已执行为
1095	// executed，不得把已执行提案报成 passed。编号、时间锁、动作原文及顺序与认可
1096	// 的记录一致；已执行提案的内容冲突仍然失败。
1097	func TestCLIRegisterReportsAcknowledgedState(t *testing.T) {
1098		binary := buildCLI(t)
1099		state := filepath.Join(t.TempDir(), "treasury.json")
1100		if _, _, code := runCLI(t, binary, state, "init", "--balance", "1000"); code != 0 {
1101			t.Fatal("init failed")
1102		}
1103		register := []string{"register", "--id", "gip-1", "--timelock", "100",
1104			"--action", "transfer:audits:250", "--action", "transfer:legal:5", "--json"}
1105	
1106		type registerResponse struct {
1107			ID                string   `json:"id"`
1108			State             string   `json:"state"`
1109			TimelockEnd       int64    `json:"timelock_end"`
1110			Actions           []string `json:"actions"`
1111			AlreadyRegistered bool     `json:"already_registered"`
1112		}
1113		runRegister := func() registerResponse {
1114			t.Helper()
1115			so, se, code := runCLI(t, binary, state, register...)
1116			if code != 0 {
1117				t.Fatalf("register exit=%d: %s", code, se)
1118			}
1119			var resp registerResponse
1120			if err := json.Unmarshal([]byte(so), &resp); err != nil {
1121				t.Fatalf("register output is not JSON: %v\n%s", err, so)
1122			}
1123			return resp
1124		}
1125		wantActions := []string{"transfer:audits:250", "transfer:legal:5"}
1126		check := func(resp registerResponse, state string, existed bool) {
1127			t.Helper()
1128			if resp.ID != "gip-1" || resp.TimelockEnd != 100 || resp.State != state ||
1129				resp.AlreadyRegistered != existed || strings.Join(resp.Actions, ",") != strings.Join(wantActions, ",") {
1130				t.Fatalf("register response = %+v, want state=%s already_registered=%v actions=%v",
1131					resp, state, existed, wantActions)
1132			}
1133		}
1134	
1135		// 首次登记：already_registered=false，state=passed。
1136		check(runRegister(), "passed", false)
1137		// 尚未执行的相同内容重试：already_registered=true，state=passed。
1138		check(runRegister(), "passed", true)
1139	
1140		// 执行后相同内容重试：state 必须是 executed，不能报成 passed。
1141		if _, se, code := runCLI(t, binary, state, "execute", "--id", "gip-1", "--now", "100"); code != 0 {
1142			t.Fatalf("execute failed: %s", se)
1143		}
1144		check(runRegister(), "executed", true)
1145	
1146		// 普通文本输出同样明确实际状态。
1147		if so, se, code := runCLI(t, binary, state, "register", "--id", "gip-1", "--timelock", "100",
1148			"--action", "transfer:audits:250", "--action", "transfer:legal:5"); code != 0 ||
1149			!strings.Contains(so, "already registered") || !strings.Contains(so, "state=executed") {
1150			t.Fatalf("text retry after execute exit=%d so=%s se=%s", code, so, se)
1151		}
1152	
1153		// 已执行提案的内容冲突（时间锁、动作原文、动作顺序）仍然失败，不返回成功对象。
1154		if so, se, code := runCLI(t, binary, state, "register", "--id", "gip-1", "--timelock", "101",
1155			"--action", "transfer:audits:250", "--action", "transfer:legal:5", "--json"); code != 1 ||
1156			!strings.Contains(se, "different timelock or actions") || strings.Contains(so, "already_registered") {
1157			t.Fatalf("timelock conflict after execute exit=%d so=%s se=%s", code, so, se)
1158		}
1159		if _, se, code := runCLI(t, binary, state, "register", "--id", "gip-1", "--timelock", "100",
1160			"--action", "transfer:legal:5", "--action", "transfer:audits:250"); code != 1 ||
1161			!strings.Contains(se, "different timelock or actions") {
1162			t.Fatalf("action order conflict after execute exit=%d: %s", code, se)
1163		}
1164	
1165		// 重试只确认已有提案：余额与首次执行凭据不被改写。
1166		if bo, _, code := runCLI(t, binary, state, "balances", "--json"); code != 0 ||
1167			!strings.Contains(bo, `"treasury": 745`) {
1168			t.Fatalf("treasury changed by register retry:\n%s", bo)
1169		}
1170		if ro, _, code := runCLI(t, binary, state, "receipt", "--id", "gip-1", "--json"); code != 0 ||
1171			!strings.Contains(ro, `"executed_at": 100`) {
1172			t.Fatalf("first execution receipt changed:\n%s", ro)
1173		}
1174	}
